Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1000009;
const int MODULUS = 1000000007;

long long computePower(long long base, long long exp, long long mod) {
    long long res = 1, b = base;
    while (exp > 0) {
        if (exp & 1) res = (res * b) % mod;
        b = (b * b) % mod;
        exp >>= 1;
    }
    return res;
}

int visitedArray[MAXN];

int main() {
#ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    int p, k;
    cin >> p >> k;
    int result = 1;
    if (k == 0) {
        for (int i = 1; i < p; ++i)
            result = (long long)result * p % MODULUS;
        cout << result << endl;
        return 0;
    }
    for (int i = 0; i < p; ++i) {
        if (visitedArray[i]) continue;
        int j = i, d = 0;
        do {
            visitedArray[j] = ++d;
            j = (long long)j * k % p;
        } while (!visitedArray[j]);
        if (computePower(k, d, p) == 1)
            result = (long long)result * p % MODULUS;
    }
    cout << result << endl;
#ifndef ONLINE_JUDGE
    fclose(stdin); fclose(stdout);
#endif
    return 0;
}
</original_code>
